#define MATRIX_DIM 512
int A[MATRIX_DIM][MATRIX_DIM];
int B[MATRIX_DIM][MATRIX_DIM];
int C[MATRIX_DIM][MATRIX_DIM];

// Optimization 1: Spatial Locality (Row-Major Traversal)
// C/C++ arrays are row-major: inner loop over columns (j) is fast.
void matrix_mul_fast() {
    for (int i = 0; i < MATRIX_DIM; i++) {
        for (int j = 0; j < MATRIX_DIM; j++) {
            for (int k = 0; k < MATRIX_DIM; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }
} // Accesses A[i][k] sequentially, maximizing cache hits.

// Optimization 2: Temporal Locality (Loop Interchange on B)
// If B was accessed via B[j][k], cache misses would dominate B access.
// (Requires B to be transposed or B accessed column-wise)
